\label{as:lip_hess}
  The function $f \in \mathcal{C}^2$ satisfies
  \begin{equation}
    \label{eq:lip_hess}
    \|{\nabla^2 f(x)-\nabla^2 f(y)} \| \leq L_2\|{x-y} \|,
    \quad x,y\in\mathcal{X}.
  \end{equation}

\label{lem:taylor_remainder}
  Let $f$ be twice continuously differentiable and satisfy~\eqref{eq:lip_hess}. Then, for every $x,y\in\mathcal{X}$,
  \begin{equation*}
    \begin{aligned}
      \bigl|f(y)&-f(x)-\left\langle\nabla f(x),y-x\right\rangle 
      -\tfrac{1}{2}\left\langle\nabla^2 f(x)(y-x),y-x\right\rangle\bigr|
      \leq\tfrac{L_2}{6}\|{y-x} \|^3.
    \end{aligned}
  \end{equation*}
  \begin{equation*}
    \|{\nabla f(y)-\nabla f(x)-\nabla^2 f(x)(y-x)} \|
    \leq\tfrac{L_2}{2}\|{y-x} \|^2.
  \end{equation*}

\label{as:stoch_grad}
  For every $x\in\mathcal{X}$, a stochastic gradient $g(x,\xi)\in\mathbb{R}^d$ satisfies
  \begin{equation}
    \label{eq:stoch_grad}
    \mathbb{E}\left[\|{g(x,\xi)-\nabla f(x)} \|^2\mid x\right] \leq \sigma_1^2.
  \end{equation}

\label{as:unbiased_grad}
  For every $x\in\mathcal{X}$, a stochastic gradient $g(x,\xi)\in\mathbb{R}^d$ satisfies:
  \begin{equation}
    \label{eq:unbiased_grad}
    \mathbb{E}[g(x,\xi)\mid x] = \nabla f(x).
  \end{equation}

\label{as:stoch_hess}
  For every $x\in\mathcal{X}$, a stochastic Hessian $H(x,\xi)\in\mathbb{R}^{d\times d}$ is symmetric and positive semidefinite almost surely, and satisfies
  \begin{equation}
    \label{eq:stoch_hess}
    \mathbb{E}\left[\|{H(x,\xi)-\nabla^2 f(x)} \|^2\mid x\right] \leq \sigma_2^2.
  \end{equation}

\label{prop:weak_convergence_guarantee}
  Let $f$ be convex. 
  Let Assumptions~\ref{as:lip_hess},~\ref{as:stoch_grad}, and~\ref{as:stoch_hess} hold. 
  Then the procedure~\eqref{eq:nikita_cn} with $\alpha_t = 3/(t+3)$ satisfies, for every  $T\geq1$,
  \begin{equation}
    \label{eq:weak_convergence_guarantee}
    \mathbb{E}\left[ f(x_T)-f^*\right]
    =\mathcal{O}\left(\sigma_1D +\tfrac{\sigma_2D^2}{T} + \tfrac{L_2 D^3}{T^2}\right).
  \end{equation}

\label{lem:basic_one_step_main}
  Let $f$ be convex and Assumption~\ref{as:lip_hess} hold. Let $M\geq0$. For the iterates of Algorithm~\ref{alg:basic_method}, we have
  \begin{equation*}
    \begin{aligned}
      \Delta_{t+1}
      \leq{}& (1-\alpha_t)\Delta_t 
      +\tfrac{\alpha_t\eta_t}{2}\left(
        \|{u_t-x^*} \|^2-\|{u_{t+1}-x^*} \|^2 \right)
      -\tfrac{\alpha_t\eta_t}{2}\|{u_{t+1}-u_t} \|^2 
       \\
      ~~~~+&~\alpha_t\left\langle\nabla f(x_t)-g_t,u_{t+1}-x^*\right\rangle + \alpha_t^2D^2\|{H_t-\nabla^2 f(x_t)} \|
      +\tfrac{\max\left\lbrace M,L_2\right\rbrace}{3}\alpha_t^3D^3.
    \end{aligned}
  \end{equation*}

\label{thm:basic_convergence}
  Let $f$ be convex. Let Assumptions~\ref{as:lip_hess},~\ref{as:stoch_grad},~\ref{as:unbiased_grad}, and~\ref{as:stoch_hess} hold. Then Algorithm~\ref{alg:basic_method} with $M\geq0$ and parameters~\eqref{eq:basic_reg} satisfies, for every $T\geq1$,
  \begin{equation*}
    \mathbb{E}\left[ f(x_T)-f^*\right]
    =\mathcal{O}\left(\tfrac{\sigma_1D}{\sqrt T} +\tfrac{\sigma_2D^2}{T} + \tfrac{\max\left\lbrace M,L_2\right\rbrace D^3}{T^2}\right).
  \end{equation*}

\label{prop:first_order_reduction}
Let $f$ be convex and satisfy~\eqref{eq:lip_grad}. Let Assumptions~~\ref{as:stoch_grad} and ~\ref{as:unbiased_grad} hold. 
Then Algorithm~\ref{alg:basic_method} with
$H_t=0$, $M=0$, and parameters~\eqref{eq:basic_reg}
satisfies, for every integer $T\geq1$,
\begin{equation*}
  \mathbb{E}[f(x_T)-f^*] 
  =
  \mathcal{O}\left(
  \tfrac{\sigma_1D}{\sqrt T}
  +\tfrac{L_1D^2}{T}
  \right).
\end{equation*}

\label{thm:optimal_convergence}
  Let $f$ be convex and satisfy Assumption~\ref{as:lip_hess}. Let $g_t$ and $H_t$ in line~\ref{lin:deriv} satisfy Assumptions~\ref{as:stoch_grad} and~\ref{as:stoch_hess}, respectively. Let stochastic gradient $\widetilde{g}_t$ in line~\ref{lin:unbiased_grad} satisfy Assumptions~\ref{as:stoch_grad},~\ref{as:unbiased_grad}. Then Algorithm~\ref{alg:optimal_method} with $M\geq L_2$ and parameters~\eqref{eq:acc_params} satisfies, for every $T\geq1$,
  \begin{equation*}
    \mathbb{E}\left[ f(w_T)-f^*\right]
    =\mathcal{O}\left(\frac{\sigma_1D}{\sqrt T}
    +\frac{\sigma_2D^2}{T^2}+\frac{MD^3}{T^{7/2}}\right).
  \end{equation*}

We use the potential
\begin{equation*}
  E_t = A_t(f(w_t)-f^*)+\frac{\lambda_t}{2}\|{z_t-x^*} \|^2.
\end{equation*}
Taking expectation and using H\"older inequality gives
\begin{equation*}
  \mathbb{E} \left[ f(w_T) - f^\ast \right] \leq \mathbb{E} \left[ E_T A_T^{-1} \right] \leq \left( \mathbb{E} E_T^2 \right)^{1/2} \left( \mathbb{E} A_T^{-2} \right)^{1/2}. 
\end{equation*}
The damping rule makes $A_T$ depend on the stochastic
derivatives. In the proof, we show that the following bounds hold
\begin{equation*}
  \left(\mathbb{E} E_T^2\right)^{1/2}\lesssim\lambda_TD^2,
  \qquad
  \left(\mathbb{E} A_T^{-2}\right)^{1/2}\lesssim\tfrac{D}{T^{7/2}}.
\end{equation*}
They give the rate of Theorem~\ref{thm:optimal_convergence}.

Using the damping condition~\eqref{eq:damping_condition},
we combine the optimality conditions of the two subproblems
in lines~\ref{lin:cubic_sub_acc} and~\ref{lin:avg_sub_acc}
with convexity to obtain
\begin{equation}
  \label{eq:potential_one_step_main}
  E_t+\tfrac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2
  \leq E_{t-1}+\tfrac{D^2}{2}(\lambda_t-\lambda_{t-1})+\delta_t+\ell_t,
\end{equation} 
where $s_t=y_t-v_t$. 
The last two terms on the right are due to the stochastic oracle errors. As in the analysis of the basic method, for the $\widetilde{g}$'s error we use the decomposition
\begin{equation*}
    z_t-x^*=(z_t-z_{t-1})+(z_{t-1}-x^*).
\end{equation*}
The term involving $z_t-z_{t-1}$ is bounded using Young's inequality
and the diameter bound, and included in $\delta_t$, together with
the errors of $g_t$ and $H_t$. The remaining term
\begin{equation*}
    \ell_t
    =
    -a_t\left\langle
    \widetilde g_t-\nabla f(y_t),
    z_{t-1}-x^*
    \right\rangle
\end{equation*}
is kept linear. Since $a_t$, $y_t$, and $z_{t-1}$ are fixed before the gradient $\widetilde g_t$ is queried, unbiasedness gives $\mathbb{E}\ell_t=0$.
Summing~\eqref{eq:potential_one_step_main}, we get
\begin{equation}
  \label{eq:potential_telescope_main}
  E_T + \frac{1}{8} \mathop{\textstyle\sum}_{t=1}^T \frac{a_t \tau_t}{\alpha_t}\|s_t\|^2 \leq \frac{\lambda_T D^2}{2} + \mathop{\textstyle\sum}_{t=1}^T \delta_t + \mathop{\textstyle\sum}_{t=1}^T \ell_t.
\end{equation}
Thus, to bound $\left( \mathbb{E} E_T^2 \right)^{1/2}$, we need to estimate second moments of the sums of $\delta$'s and $\ell$'s. Since $\ell_t$ has zero mean conditionally on the past, the cross terms vanish and
\begin{equation*}
  \mathbb{E} \left( \mathop{\textstyle\sum}_{t=1}^T \ell_t \right)^2 = \mathop{\textstyle\sum}_{t=1}^T \mathbb{E} \ell_t^2 \leq \mathop{\textstyle\sum}_{t=1}^T  D^2 \sigma_1^2 \mathbb{E} a_t^2\lesssim \sigma_1^2 T^6 \stackrel{\eqref{eq:acc_params}}{\lesssim} \lambda_T^2 D^4,
\end{equation*}
where $\tau_t \geq \beta_t$ and~\eqref{eq:damping_condition} give
$a_t\leq t^{3/2}/(\alpha_tD)$. The contraction bound $\|{s_t} \|\leq\alpha_tD$
and the regularization parameters~\eqref{eq:acc_params}
also yield a second-moment bound of order
$\lambda_T^2D^4$ for $\mathop{\textstyle\sum}_{t=1}^T\delta_t$ (see Lemma~\ref{lem:optimal_error_moments}). Consequently, 
\begin{equation}
  \label{eq:potential_rate}
  \left( \mathbb{E}  E_T^2 \right) ^{1/2} \lesssim \lambda_T D^2.
\end{equation} 
It remains to show the bound on $\left( \mathbb{E} A_T^{-2} \right)^{1/2}$.  By~\eqref{eq:A_relation_main}, there are two types of iterations. If all iterations $t=2,\ldots,T$ are undamped, then
\begin{equation*}
  A_T^{-1} = A_1^{-1}\mathop{\textstyle\prod}_{t=2}^T (1-\alpha_t) \stackrel{\eqref{eq:acc_params}}{\lesssim} \frac{D}{T^4}.
\end{equation*}
On damped iterations, $a_t=\lambda_t/(\alpha_t\tau_t)$, so
\begin{equation*}
  A_t^{-1}\leq(1-\alpha_t)A_{t-1}^{-1}+\alpha_t^3\left(\tfrac{D}{t^{3/2}}+\|{s_t} \|\right),
\end{equation*}
while at undamped iterations the last term is absent. Multiplying by $t(t+1)(t+2)(t+3)$ and summing gives
\begin{equation*}
  A_T^{-1}\lesssim\frac{D}{T^{7/2}}
  +\frac{1}{T^4}\sum_{\substack{t\leq T\\a_t<\alpha_tA_t}}\frac{\|{s_t} \|}{\alpha_t}.
\end{equation*}
On damped iterations,~\eqref{eq:damping_condition}
holds with equality, so the squared-step term
in~\eqref{eq:potential_one_step_main} is
$\lambda_t\|{s_t} \|^2/(8\alpha_t^2)$.
A weighted summation of the normalized one-step bound
controls the second moment of the sum above by
$\mathcal{O}(D^2T)$  (see Lemma~\ref{lem:optimal_movement}).
Substituting this estimate and using Minkowski inequality yields
\begin{equation*}
  \left(\mathbb{E} A_T^{-2}\right)^{1/2}
  \lesssim\frac{D}{T^{7/2}}.
\end{equation*}
Combining this bound with~\eqref{eq:potential_rate} and using the definition of $\lambda_t$ yields the desired rate. 

The full proof is given in Appendix~\ref{sec:proof_optimal}.

\label{lem:basic_one_step}
  Let $f$ be convex and satisfy Assumption~\ref{as:lip_hess}, and let $M\geq 0$. For the iterates of Algorithm~\ref{alg:basic_method}, with $0<\alpha_t\leq1$, $\eta_t\geq0$, and $H_t\succeq0$, we have
  \begin{equation}
    \label{eq:basic_one_step}
    \begin{aligned}
      f(x_{t+1})-f^*
      \leq{}& (1-\alpha_t)\left( f(x_t)-f^*\right) \\
      &+\frac{\alpha_t\eta_t}{2}\left(
        \|{u_t-x^*} \|^2-\|{u_{t+1}-x^*} \|^2-\|{u_{t+1}-u_t} \|^2
      \right) \\
      &+\alpha_t\left\langle\nabla f(x_t)-g_t,u_{t+1}-x^*\right\rangle
      +\alpha_t^2D^2\|{H_t-\nabla^2 f(x_t)} \|
      +\frac{\max\left\lbrace M,L_2\right\rbrace}{3}\alpha_t^3D^3.
    \end{aligned}
  \end{equation}

Let $f$ be convex. Let Assumptions~\ref{as:lip_hess},~\ref{as:stoch_grad},~\ref{as:unbiased_grad}, and~\ref{as:stoch_hess} hold. Then Algorithm~\ref{alg:basic_method} with $M\geq0$ and parameters~\eqref{eq:basic_reg} satisfies, for every integer $T\geq1$,
  \begin{equation}
    \label{eq:basic_rate}
      \mathbb{E}\left[ f(x_T)-f^*\right]
      \leq\frac{9\max\left\lbrace M,L_2\right\rbrace D^3}{(T+1)(T+2)} 
      +\frac{9\sigma_2D^2}{2(T+2)}+\frac{9\sigma_1D}{4\sqrt T}.
  \end{equation}
  In particular, if $M\geq0$ and $M=\mathcal{O}(L_2)$ with an absolute implied constant, then
  \begin{equation*}
    \mathbb{E}\left[ f(x_T)-f^*\right]
    =\mathcal{O}\left(\frac{\sigma_1D}{\sqrt T} + \frac{\sigma_2D^2}{T} + \frac{L_2D^3}{T^2}\right).
  \end{equation*}

Suppose first that $\sigma_1>0$, so that $\eta_t>0$. By~\eqref{eq:unbiased_grad} we have
  \begin{equation*}
    \mathbb{E}\left[\left\langle\nabla f(x_t)-g_t,u_t-x^*\right\rangle
      \mid x_t,u_t\right]=0.
  \end{equation*}
  Splitting $u_{t+1}-x^*=(u_{t+1}-u_t)+(u_t-x^*)$ and applying Young's inequality gives
  \begin{gather*}
    \mathbb{E}\left[\left\langle\nabla f(x_t)-g_t,u_{t+1}-x^*\right\rangle
      -\frac{\eta_t}{2}\|{u_{t+1}-u_t} \|^2\right] 
    =\mathbb{E}\left[\left\langle\nabla f(x_t)-g_t,u_{t+1}-u_t\right\rangle
      -\frac{\eta_t}{2}\|{u_{t+1}-u_t} \|^2\right] \\
    \leq\frac{1}{2\eta_t}\mathbb{E}\|{g_t-\nabla f(x_t)} \|^2
    \stackrel{\eqref{eq:stoch_grad}}{\leq}\frac{\sigma_1^2}{2\eta_t}.
  \end{gather*}
  Also, by~\eqref{eq:stoch_hess},
  \begin{equation*}
    \mathbb{E}\|{H_t-\nabla^2 f(x_t)} \|
    \leq\left(\mathbb{E}\|{H_t-\nabla^2 f(x_t)} \|^2\right)^{1/2}
    \leq\sigma_2.
  \end{equation*}
  Taking expectations in~\eqref{eq:basic_one_step} and substituting these bounds yields
  \begin{equation}
    \label{eq:basic_expected_step}
    \begin{aligned}
      \mathbb{E}\left[ f(x_{t+1})-f^*\right]
      \leq{}&(1-\alpha_t)\mathbb{E}\left[ f(x_t)-f^*\right] 
      +\frac{\alpha_t\eta_t}{2}\left(
        \mathbb{E}\|{u_t-x^*} \|^2-\mathbb{E}\|{u_{t+1}-x^*} \|^2
      \right)  \\
      &+\frac{\max\left\lbrace M,L_2\right\rbrace}{3}\alpha_t^3D^3
      +\alpha_t^2\sigma_2D^2+\frac{\alpha_t\sigma_1^2}{2\eta_t}.
    \end{aligned}
  \end{equation}
  Multiplying~\eqref{eq:basic_expected_step} by $(t+1)(t+2)(t+3)$ and substituting $\alpha_t=3/(t+3)$ gives
  \begin{gather*}
      (t+1)(t+2)(t+3)\mathbb{E}\left[ f(x_{t+1})-f^*\right]
      -t(t+1)(t+2)\mathbb{E}\left[ f(x_t)-f^*\right] \\
      \leq\frac{3}{2}(t+1)(t+2)\eta_t
        \left(\mathbb{E}\|{u_t-x^*} \|^2-\mathbb{E}\|{u_{t+1}-x^*} \|^2\right) \\
      +9\max\left\lbrace M,L_2\right\rbrace D^3\frac{(t+1)(t+2)}{(t+3)^2}
      +9\sigma_2D^2\frac{(t+1)(t+2)}{t+3}
      +\frac{3\sigma_1^2}{2}\frac{(t+1)(t+2)}{\eta_t}.
  \end{gather*}
  Now sum it over $t=0,\ldots,T-1$. The left-hand side telescopes:
  \begin{gather*}
    \sum_{t=0}^{T-1}\left(
      (t+1)(t+2)(t+3)\mathbb{E}\left[ f(x_{t+1})-f^*\right]
      -t(t+1)(t+2)\mathbb{E}\left[ f(x_t)-f^*\right]
    \right)\\
    =T(T+1)(T+2)\mathbb{E}\left[ f(x_T)-f^*\right],
  \end{gather*}
  where we used $\alpha_0=1$. Next,
  \begin{equation}
    \label{eq:basic_summed}
    \begin{aligned}
      T(T+1)(T+2)\mathbb{E}\left[ f(x_T)-f^*\right]
      \leq{}&\frac{3}{2}\sum_{t=0}^{T-1}(t+1)(t+2)\eta_t
        \left(\mathbb{E}\|{u_t-x^*} \|^2-\mathbb{E}\|{u_{t+1}-x^*} \|^2\right) \\
      &+9\max\left\lbrace M,L_2\right\rbrace D^3\sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{(t+3)^2}\\
      &+9\sigma_2D^2\sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{t+3}
      +\frac{3\sigma_1^2}{2}\sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{\eta_t}.
    \end{aligned}
  \end{equation}
  Let us consider the first sum in inequality above. 
  \begin{gather*}
    \sum_{t=0}^{T-1}(t+1)(t+2)\eta_t
      \left(\mathbb{E}\|{u_t-x^*} \|^2-\mathbb{E}\|{u_{t+1}-x^*} \|^2\right) \\
    =2\eta_0\mathbb{E}\|{u_0-x^*} \|^2
    +\sum_{t=0}^{T-2}\left((t+2)(t+3)\eta_{t+1}-(t+1)(t+2)\eta_t\right)
      \mathbb{E}\|{u_{t+1}-x^*} \|^2\\
    -T(T+1)\eta_{T-1}\mathbb{E}\|{u_T-x^*} \|^2 \\
    \leq D^2\left[2\eta_0+
      \sum_{t=0}^{T-2}\left((t+2)(t+3)\eta_{t+1}-(t+1)(t+2)\eta_t\right)\right] \\
   =T(T+1)\eta_{T-1}D^2 \stackrel{\eqref{eq:basic_reg}}{=}\sigma_1D T(T+1)\sqrt T.
  \end{gather*}
  The remaining sums satisfy
  \begin{gather*}
    \sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{(t+3)^2}\leq T,
    \qquad
    \sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{t+3}\leq\sum_{t=0}^{T-1}(t+1)=\frac{T(T+1)}{2}, \\
    \sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{\eta_t}
    \stackrel{\eqref{eq:basic_reg}}{=}\frac{D}{\sigma_1}\sum_{t=0}^{T-1}(t+2)\sqrt{t+1} 
    \leq\frac{D\sqrt T}{\sigma_1}\sum_{t=0}^{T-1}(t+2)
    =\frac{D\sqrt T T(T+3)}{2\sigma_1}.
  \end{gather*}
  Substituting into~\eqref{eq:basic_summed} and dividing by $T(T+1)(T+2)$, we obtain
  \begin{gather*}
    \mathbb{E}\left[ f(x_T)-f^*\right]
    \leq\frac{9\max\left\lbrace M,L_2\right\rbrace D^3}{(T+1)(T+2)}
    +\frac{9\sigma_2D^2}{2(T+2)}
    +\frac{3\sigma_1D\sqrt T}{2(T+2)}
    +\frac{3\sigma_1D\sqrt T(T+3)}{4(T+1)(T+2)} \\
    =\frac{9\max\left\lbrace M,L_2\right\rbrace D^3}{(T+1)(T+2)}
    +\frac{9\sigma_2D^2}{2(T+2)}
    +\frac{3\sigma_1D\sqrt T(3T+5)}{4(T+1)(T+2)}.
  \end{gather*}
  Since $T(3T+5)\leq3(T+1)(T+2)$, this proves~\eqref{eq:basic_rate}.

  If $\sigma_1=0$, then $\eta_t=0$ and $g_t=\nabla f(x_t)$. The gradient error and quadratic regularization terms in~\eqref{eq:basic_one_step} vanish. The same summation then proves~\eqref{eq:basic_rate} without its last term.

Let $\Delta_t=f(x_t)-f^*$. Applying Lemma~\ref{lem:basic_one_step} with $M=\eta_t=0$ and using Cauchy--Schwarz,~\eqref{eq:stoch_grad}, and~\eqref{eq:stoch_hess} gives
  \begin{equation*}
    \mathbb{E}\Delta_{t+1}
    \leq(1-\alpha_t)\mathbb{E}\Delta_t+\alpha_t\sigma_1D
    +\alpha_t^2\sigma_2D^2+\frac{L_2}{3}\alpha_t^3D^3.
  \end{equation*}
  Multiplying by $(t+1)(t+2)(t+3)$, substituting $\alpha_t=3/(t+3)$, and summing over $t=0,\ldots,T-1$ yields
  \begin{gather*}
    T(T+1)(T+2)\mathbb{E}\Delta_T\\
    \leq3\sigma_1D\sum_{t=0}^{T-1}(t+1)(t+2)
    +9\sigma_2D^2\sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{t+3} 
    +9L_2D^3\sum_{t=0}^{T-1}\frac{(t+1)(t+2)}{(t+3)^2} \\
    \leq T(T+1)(T+2)\sigma_1D
    +\frac{9T(T+1)}{2}\sigma_2D^2+9TL_2D^3,
  \end{gather*}
  where the initial term vanishes since $\alpha_0=1$. Dividing by $T(T+1)(T+2)$ gives
  \begin{equation*}
    \mathbb{E}\left[ f(x_T)-f^*\right]
    \leq\sigma_1D+\frac{9\sigma_2D^2}{2(T+2)}
    +\frac{9L_2D^3}{(T+1)(T+2)},
  \end{equation*}
  which proves~\eqref{eq:weak_convergence_guarantee}.

\label{lem:optimal_geometry}
  For the iterates of Algorithm~\ref{alg:optimal_method_appendix} and every $t\geq1$,
  \begin{equation}
    \label{eq:optimal_geometry}
    s_t=\alpha_t(u_t-z_{t-1}),
    \qquad \|{s_t} \|\leq\alpha_tD.
  \end{equation}
  The weights satisfy
  \begin{equation}
    \label{eq:optimal_cap}
    0<a_t\leq\alpha_tA_t,
    \qquad 0<a_t\alpha_t\tau_t\leq\lambda_t.
  \end{equation}
  Consequently,
  \begin{equation}
    \label{eq:optimal_averaging}
    w_t=\left(1-\frac{a_t}{\alpha_tA_t}\right) w_{t-1}
    +\frac{a_t}{\alpha_tA_t}y_t.
  \end{equation}
  Moreover,
  \begin{equation}
    \label{eq:optimal_model_condition}
    \left\langle g_t+H_ts_t+\tau_ts_t,x-u_t\right\rangle\geq0,
    \quad x\in\mathcal{X}.
  \end{equation}

By the definitions of $v_t$ and $y_t$,
  \begin{gather*}
    s_t=(1-\alpha_t)w_{t-1}+\alpha_tu_t
    -\left((1-\alpha_t)w_{t-1}+\alpha_tz_{t-1}\right)
    =\alpha_t(u_t-z_{t-1}),\\
    \|{s_t} \|=\alpha_t\|{u_t-z_{t-1}} \|\leq\alpha_tD.
  \end{gather*}
  For $t\geq2$,~\eqref{eq:optimal_weights} gives $a_t>0$ and
  \begin{gather*}
    a_t(1-\alpha_t)\leq\alpha_tA_{t-1},
    \qquad a_t\alpha_t\tau_t\leq\lambda_t,
    \qquad a_t=a_t(1-\alpha_t)+\alpha_ta_t
    \leq\alpha_t(A_{t-1}+a_t)=\alpha_tA_t.
  \end{gather*}
  At $t=1$,~\eqref{eq:optimal_initialization} gives $a_1=\alpha_1A_1>0$ and $a_1\alpha_1\tau_1=\lambda_1$. Thus~\eqref{eq:optimal_cap} holds for every $t\geq1$. By~\eqref{eq:optimal_updates} and~\eqref{eq:optimal_predictor},
  \begin{equation*}
    A_tw_t=A_{t-1}w_{t-1}+a_tu_t
    =(A_t-a_t)w_{t-1}
    +\frac{a_t}{\alpha_t}\left( y_t-(1-\alpha_t)w_{t-1}\right)
    =\left( A_t-\frac{a_t}{\alpha_t}\right) w_{t-1}
    +\frac{a_t}{\alpha_t}y_t,
  \end{equation*}
  which proves~\eqref{eq:optimal_averaging}. Finally,
  \begin{gather*}
    \nabla\Omega_t(u_t)
    \stackrel{\eqref{eq:optimal_model}}{=}
    g_t+\alpha_tH_t(u_t-z_{t-1})
    +\alpha_t\beta_t(u_t-z_{t-1})
    +\lambda_t\alpha_t^2\|{u_t-z_{t-1}} \|(u_t-z_{t-1})\\
    =g_t+H_ts_t+\left(\beta_t+\lambda_t\|{s_t} \|\right) s_t
    \stackrel{\eqref{eq:optimal_damping}}{=}g_t+H_ts_t+\tau_ts_t.
  \end{gather*}
  Optimality of $u_t$ over $\mathcal{X}$ gives~\eqref{eq:optimal_model_condition}.

\label{lem:optimal_one_step}
  For every $t\geq1$,
  \begin{equation}
    \label{eq:optimal_one_step}
    \begin{aligned}
      E_t+\frac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2
      \leq{}&E_{t-1}+\frac{D^2}{2}(\lambda_t-\lambda_{t-1})\\
      &+\min\left\lbrace
        \begin{aligned}
          &\frac{4}{\alpha_t^2\lambda_t}
          \left(\|{H_t-\nabla^2 f(v_t)} \|^2+\frac{t^3}{D^2}\|{g_t-\nabla f(v_t)} \|^2\right),\\
          &\frac{D}{\alpha_t}\|{H_t-\nabla^2 f(v_t)} \|
          +\frac{t^{3/2}}{\alpha_t}\|{g_t-\nabla f(v_t)} \|
        \end{aligned}
      \right\rbrace\\
      &+\min\left\lbrace\frac{2t^3\|{\widetilde g_t-\nabla f(y_t)} \|^2}{\alpha_t^2\lambda_tD^2},
                  \frac{t^{3/2}\|{\widetilde g_t-\nabla f(y_t)} \|}{\alpha_t}\right\rbrace
      -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle.
    \end{aligned}
  \end{equation}

By~\eqref{eq:optimal_cap}, $0<a_t/(\alpha_tA_t)\leq1$. Thus, by~\eqref{eq:optimal_averaging} and convexity,
\begin{gather*}
  A_tf(w_t)
  =A_tf\left(\left(1-\frac{a_t}{\alpha_tA_t}\right) w_{t-1}
  +\frac{a_t}{\alpha_tA_t}y_t\right)
  \leq\left( A_t-\frac{a_t}{\alpha_t}\right) f(w_{t-1})
  +\frac{a_t}{\alpha_t}f(y_t).
\end{gather*}
Using $A_t-A_{t-1}=a_t$, we obtain
\begin{gather*}
  A_t(f(w_t)-f^*)-A_{t-1}(f(w_{t-1})-f^*)\\
  \leq\left( A_t-\frac{a_t}{\alpha_t}-A_{t-1}\right) f(w_{t-1})
  +\frac{a_t}{\alpha_t}f(y_t)-a_tf^*\\
  =\frac{a_t}{\alpha_t}
  \left( f(y_t)-(1-\alpha_t)f(w_{t-1})-\alpha_tf^*\right)\\
  \leq\frac{a_t}{\alpha_t}
  \left\langle\nabla f(y_t),y_t-(1-\alpha_t)w_{t-1}-\alpha_tx^*\right\rangle
  =a_t\left\langle\nabla f(y_t),u_t-x^*\right\rangle.
\end{gather*}

  Hence,
  \begin{equation}
    \label{eq:optimal_convexity}
    A_t(f(w_t)-f^*)\leq A_{t-1}(f(w_{t-1})-f^*)
    +a_t\left\langle\nabla f(y_t),u_t-x^*\right\rangle.
  \end{equation}

  The optimality condition for~\eqref{eq:optimal_updates}, multiplied by $a_t>0$, gives
  \begin{equation*}
    \left\langle a_t\widetilde g_t+\lambda_t(z_t-z_{t-1}),x^*-z_t\right\rangle\geq0.
  \end{equation*}
  Since
  \begin{equation*}
    \|{z_{t-1}-x^*} \|^2
    =\|{z_t-x^*} \|^2+\|{z_t-z_{t-1}} \|^2
    -2\left\langle z_t-z_{t-1},z_t-x^*\right\rangle,
  \end{equation*}
  we obtain
  \begin{gather*}
    a_t\left\langle\widetilde g_t,z_t-x^*\right\rangle
    \leq-\lambda_t\left\langle z_t-z_{t-1},z_t-x^*\right\rangle
    =\frac{\lambda_t}{2}
    \left(\|{z_{t-1}-x^*} \|^2-\|{z_t-x^*} \|^2-\|{z_t-z_{t-1}} \|^2\right).
  \end{gather*}
  Rearranging,
  \begin{equation}
    \label{eq:three_dist_bound}
    \frac{\lambda_t}{2}
    \left( \|{z_t-x^*} \|^2 - \|{z_{t-1}-x^*} \|^2 \right) \leq a_t\left\langle\widetilde g_t,x^* - z_t \right\rangle -\frac{\lambda_t}{2}\|{z_t-z_{t-1}} \|^2.
  \end{equation}
  Combining this bound with~\eqref{eq:optimal_convexity}, $\lambda_t\geq\lambda_{t-1}$, and $\|{z_{t-1}-x^*} \|\leq D$, we obtain
  \begin{gather*}
    E_t-E_{t-1}
    \stackrel{\eqref{eq:optimal_energy}}{=}
    A_t(f(w_t)-f^*)-A_{t-1}(f(w_{t-1})-f^*)\\
    +\frac{\lambda_t}{2}\left(\|{z_t-x^*} \|^2-\|{z_{t-1}-x^*} \|^2\right)
    +\frac{\lambda_t-\lambda_{t-1}}{2}\|{z_{t-1}-x^*} \|^2\\
    \stackrel{\eqref{eq:optimal_convexity}}{\leq}a_t\left\langle\nabla f(y_t),u_t-x^*\right\rangle
    +\frac{\lambda_t}{2}\left(\|{z_t-x^*} \|^2-\|{z_{t-1}-x^*} \|^2\right)\\
    +\frac{\lambda_t-\lambda_{t-1}}{2}\|{z_{t-1}-x^*} \|^2 \\
    \stackrel{\eqref{eq:three_dist_bound}}{\leq} 
    a_t\left\langle\nabla f(y_t),u_t-z_t\right\rangle
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-x^*\right\rangle 
    -\frac{\lambda_t}{2}\|{z_t-z_{t-1}} \|^2
    + \frac{D^2}{2}(\lambda_t-\lambda_{t-1}).
  \end{gather*}
  Applying~\eqref{eq:optimal_model_condition} at $x=z_t$ gives
  \begin{equation*}
    \left\langle\nabla f(y_t),u_t-z_t\right\rangle
    \leq\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle.
  \end{equation*}
  Consequently,
  \begin{equation}
    \label{eq:optimal_energy_projection}
    \begin{aligned}
      E_t-E_{t-1}\leq{}&\frac{D^2}{2}(\lambda_t-\lambda_{t-1})
      -\frac{\lambda_t}{2}\|{z_t-z_{t-1}} \|^2\\
      &+a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
      -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-x^*\right\rangle.
    \end{aligned}
  \end{equation}

  We first bound the term containing $\widetilde g_t-\nabla f(y_t)$. Splitting $z_t-x^*=(z_{t-1}-x^*)+(z_t-z_{t-1})$, we get
  \begin{gather*}
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-x^*\right\rangle
    -\frac{\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
    =-a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-z_{t-1}\right\rangle
    -\frac{\lambda_t}{8}\|{z_t-z_{t-1}} \|^2.
  \end{gather*}
  Young's inequality and $\|{z_t-z_{t-1}} \|\leq D$ give, respectively,
  \begin{gather*}
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-z_{t-1}\right\rangle
    -\frac{\lambda_t}{8}\|{z_t-z_{t-1}} \|^2
    \leq\frac{2a_t^2}{\lambda_t}\|{\widetilde g_t-\nabla f(y_t)} \|^2,\\
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_t-z_{t-1}\right\rangle
    -\frac{\lambda_t}{8}\|{z_t-z_{t-1}} \|^2
    \leq a_tD\|{\widetilde g_t-\nabla f(y_t)} \|.
  \end{gather*}
  Taking the smaller of these two bounds, we obtain
  \begin{equation}
    \label{eq:optimal_fresh_gradient_error}
    \begin{aligned}
      &-a_t\langle \widetilde g_t  -\nabla f(y_t),z_t-x^*\rangle
      -\frac{\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
      &\leq-a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle\\
      &\quad+\min\left\lbrace\frac{2a_t^2}{\lambda_t}\|{\widetilde g_t-\nabla f(y_t)} \|^2,
                  a_tD\|{\widetilde g_t-\nabla f(y_t)} \|\right\rbrace.
    \end{aligned}
  \end{equation}

  Applying~\eqref{eq:optimal_fresh_gradient_error} in~\eqref{eq:optimal_energy_projection}, we obtain
  \begin{gather*}
    E_t-E_{t-1}
    \leq\frac{D^2}{2}(\lambda_t-\lambda_{t-1})
    +a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
    -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
    -a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle
    +\min\left\lbrace\frac{2a_t^2}{\lambda_t}\|{\widetilde g_t-\nabla f(y_t)} \|^2,
                a_tD\|{\widetilde g_t-\nabla f(y_t)} \|\right\rbrace.
  \end{gather*}
  It remains to bound
  \begin{equation}
    \label{eq:remaining_bound}
    a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
    -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2.
  \end{equation}
  We rewrite
  \begin{equation*}
    \nabla f(y_t)-g_t-H_ts_t
    =\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t
    -(H_t-\nabla^2 f(v_t))s_t-(g_t-\nabla f(v_t)).
  \end{equation*}
  Since $s_t=y_t-v_t$, Lemma~\ref{lem:taylor_remainder} with $x=v_t$ and $y=y_t$, and using $\lambda_t\geq2M\geq2L_2$ and $\tau_t\geq\lambda_t\|{s_t} \|$, we obtain
  \begin{equation}
    \label{eq:optimal_taylor}
    \|{\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t} \|
    \leq\frac{L_2}{2}\|{s_t} \|^2
    \leq\frac{\lambda_t}{4}\|{s_t} \|^2
    \leq\frac{\tau_t}{4}\|{s_t} \|.
  \end{equation}

  For every vector $h\in\mathbb{R}^d$, Young's inequality and~\eqref{eq:optimal_cap} give
  \begin{equation}
    \label{eq:optimal_young_bound}
    \begin{aligned}
     a_t\left\langle h,u_t-z_t\right\rangle-\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2
       &\stackrel{\eqref{eq:optimal_geometry}}{=}
      \frac{a_t}{\alpha_t}\left\langle h,s_t\right\rangle-a_t\left\langle h,z_t-z_{t-1}\right\rangle
      -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
      &\leq
      \frac{a_t}{\alpha_t}\left\langle h,s_t\right\rangle+\frac{2a_t^2}{3\lambda_t}\|{h} \|^2
      \stackrel{\eqref{eq:optimal_cap}}{\leq}
      \frac{a_t}{\alpha_t}\left\langle h,s_t\right\rangle+\frac{2a_t}{3\alpha_t\tau_t}\|{h} \|^2.
    \end{aligned}
  \end{equation}
  Substituting $h=(h+\tau_ts_t)-\tau_ts_t$, we obtain
  \begin{equation}
    \label{eq:optimal_shift_bound}
    \begin{aligned}
      \frac{a_t}{\alpha_t}\left\langle h,s_t\right\rangle
      &+\frac{2a_t}{3\alpha_t\tau_t}\|{h} \|^2
      =\frac{2a_t}{3\alpha_t\tau_t}\|{h+\tau_ts_t} \|^2
      -\frac{a_t}{3\alpha_t}\left\langle h+\tau_ts_t,s_t\right\rangle
      -\frac{a_t\tau_t}{3\alpha_t}\|{s_t} \|^2\\
      &\leq
      \left(\frac{2a_t}{3\alpha_t\tau_t}+\frac{a_t}{3\alpha_t\tau_t}\right)\|{h+\tau_ts_t} \|^2
      +\left(\frac{a_t\tau_t}{12\alpha_t}-\frac{a_t\tau_t}{3\alpha_t}\right)\|{s_t} \|^2
      =\frac{a_t}{\alpha_t\tau_t}\|{h+\tau_ts_t} \|^2
      -\frac{a_t\tau_t}{4\alpha_t}\|{s_t} \|^2.
    \end{aligned}
  \end{equation}
  Combining~\eqref{eq:optimal_young_bound} and~\eqref{eq:optimal_shift_bound} gives
  \begin{equation}
    \label{eq:optimal_square_bound}
    a_t\left\langle h,u_t-z_t\right\rangle-\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2
    \leq-\frac{a_t\tau_t}{4\alpha_t}\|{s_t} \|^2
    +\frac{a_t}{\alpha_t\tau_t}\|{h+\tau_ts_t} \|^2.
  \end{equation}

  We apply~\eqref{eq:optimal_square_bound} with two choices of $h$ to bound~\eqref{eq:remaining_bound}.
  \begin{itemize}
    \item Let $h=\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t$. Then~\eqref{eq:optimal_square_bound} gives
    \begin{gather*}
      a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
      -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
      \leq-\frac{a_t\tau_t}{4\alpha_t}\|{s_t} \|^2
      +\frac{a_t}{\alpha_t\tau_t}\|{\nabla f(y_t)-g_t-H_ts_t} \|^2.
    \end{gather*}
    By Young's inequality we have
    \begin{gather*}
      \|{\nabla f(y_t)-g_t-H_ts_t} \|^2\\
      =\|{\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t
      -(H_t-\nabla^2 f(v_t))s_t-(g_t-\nabla f(v_t))} \|^2\\
      \leq
      2\|{\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t} \|^2
      +4\|{H_t-\nabla^2 f(v_t)} \|^2\|{s_t} \|^2
      +4\|{g_t-\nabla f(v_t)} \|^2\\
      \stackrel{\eqref{eq:optimal_taylor}}{\leq}
      \frac{\tau_t^2}{8}\|{s_t} \|^2
      +4\|{H_t-\nabla^2 f(v_t)} \|^2\|{s_t} \|^2
      +4\|{g_t-\nabla f(v_t)} \|^2.
    \end{gather*}
    Substituting this bound gives
    \begin{equation}
      \label{eq:optimal_quadratic_error}
      \begin{aligned}
        &a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
        -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
        &\leq-\frac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2
        +\frac{4a_t}{\alpha_t\tau_t}
        \left(\|{H_t-\nabla^2 f(v_t)} \|^2\|{s_t} \|^2+\|{g_t-\nabla f(v_t)} \|^2\right).
      \end{aligned}
    \end{equation}

    \item Let $h=\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t-\tau_ts_t$. Then
    \begin{gather*}
      a_t\left\langle h,u_t-z_t\right\rangle-\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2
      \stackrel{\eqref{eq:optimal_square_bound}}{\leq}
      -\frac{a_t\tau_t}{4\alpha_t}\|{s_t} \|^2
      +\frac{a_t}{\alpha_t\tau_t}\|{\nabla f(y_t)-\nabla f(v_t)-\nabla^2 f(v_t)s_t} \|^2\\
      \stackrel{\eqref{eq:optimal_taylor}}{\leq}
      -\frac{a_t\tau_t}{4\alpha_t}\|{s_t} \|^2
      +\frac{a_t}{\alpha_t\tau_t}\frac{\tau_t^2}{16}\|{s_t} \|^2
      =-\frac{3a_t\tau_t}{16\alpha_t}\|{s_t} \|^2
      \leq-\frac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2.
    \end{gather*}
    Since
    \begin{equation*}
      \nabla f(y_t)-g_t-H_ts_t-\tau_ts_t
      =h-(H_t-\nabla^2 f(v_t))s_t-(g_t-\nabla f(v_t)),
    \end{equation*}
    and $\|{u_t-z_t} \|\leq D$, we also have
    \begin{equation}
      \label{eq:optimal_linear_error}
      \begin{aligned}
        &a_t\left\langle\nabla f(y_t)-g_t-H_ts_t-\tau_ts_t,u_t-z_t\right\rangle
        -\frac{3\lambda_t}{8}\|{z_t-z_{t-1}} \|^2\\
        &\leq-\frac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2
        +a_tD\left(\|{H_t-\nabla^2 f(v_t)} \|\|{s_t} \|+\|{g_t-\nabla f(v_t)} \|\right).
      \end{aligned}
    \end{equation}
  \end{itemize}

  Taking the smaller right-hand side of~\eqref{eq:optimal_quadratic_error} and~\eqref{eq:optimal_linear_error}, and combining with~\eqref{eq:optimal_fresh_gradient_error} in~\eqref{eq:optimal_energy_projection}, we obtain
  \begin{equation}
    \label{eq:optimal_energy_combined}
    \begin{aligned}
      E_t+\frac{a_t\tau_t}{8\alpha_t}\|{s_t} \|^2
      \leq{}&E_{t-1}+\frac{D^2}{2}(\lambda_t-\lambda_{t-1})\\
      &+\min\left\lbrace
        \begin{aligned}
          &\frac{4a_t}{\alpha_t\tau_t}
          \left(\|{H_t-\nabla^2 f(v_t)} \|^2\|{s_t} \|^2+\|{g_t-\nabla f(v_t)} \|^2\right),\\
          &a_tD\left(\|{H_t-\nabla^2 f(v_t)} \|\|{s_t} \|+\|{g_t-\nabla f(v_t)} \|\right)
        \end{aligned}
      \right\rbrace\\
      &+\min\left\lbrace\frac{2a_t^2}{\lambda_t}\|{\widetilde g_t-\nabla f(y_t)} \|^2,
                  a_tD\|{\widetilde g_t-\nabla f(y_t)} \|\right\rbrace\\
      &-a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle.
    \end{aligned}
  \end{equation}
  Finally, we bound random coefficients including $\|s_t\|,~\|\tau_t\|,~a_t$  using $\tau_t\geq\lambda_t\|{s_t} \|$ and $\tau_t\geq\beta_t$ . First,
  \begin{equation}
    \label{eq:optimal_weight_bound}
    a_t\stackrel{\eqref{eq:optimal_cap}}{\leq}
    \frac{\lambda_t}{\alpha_t\tau_t}
    \leq\frac{\lambda_t}{\alpha_t\beta_t}
    \stackrel{\eqref{eq:optimal_reg}}{=}
    \frac{\lambda_t}{\alpha_t(\lambda_tD/t^{3/2})}
    =\frac{t^{3/2}}{\alpha_tD}.
  \end{equation}
  Consequently,
  \begin{gather*}
    \frac{a_t\|{s_t} \|^2}{\alpha_t\tau_t}
    \stackrel{\eqref{eq:optimal_cap}}{\leq}
    \frac{\lambda_t\|{s_t} \|^2}{\alpha_t^2\tau_t^2}
    =\frac{1}{\alpha_t^2\lambda_t}\left(\frac{\lambda_t\|{s_t} \|}{\tau_t}\right)^2
    \leq\frac{1}{\alpha_t^2\lambda_t},\\
    \frac{a_t}{\alpha_t\tau_t}
    \stackrel{\eqref{eq:optimal_cap}}{\leq}
    \frac{\lambda_t}{\alpha_t^2\tau_t^2}
    \leq\frac{\lambda_t}{\alpha_t^2\beta_t^2}
    \stackrel{\eqref{eq:optimal_reg}}{=}
    \frac{\lambda_t}{\alpha_t^2(\lambda_tD/t^{3/2})^2}
    =\frac{t^3}{\alpha_t^2\lambda_tD^2},\\
    a_tD\|{s_t} \|
    \stackrel{\eqref{eq:optimal_cap}}{\leq}
    \frac{\lambda_tD\|{s_t} \|}{\alpha_t\tau_t}
    =\frac{D}{\alpha_t}\frac{\lambda_t\|{s_t} \|}{\tau_t}
    \leq\frac{D}{\alpha_t},\qquad
    a_tD\stackrel{\eqref{eq:optimal_weight_bound}}{\leq}
    \frac{t^{3/2}}{\alpha_tD}D
    =\frac{t^{3/2}}{\alpha_t},\\
    \frac{2a_t^2}{\lambda_t}
    \stackrel{\eqref{eq:optimal_weight_bound}}{\leq}
    \frac{2}{\lambda_t}\left(\frac{t^{3/2}}{\alpha_tD}\right)^2
    =\frac{2t^3}{\alpha_t^2\lambda_tD^2}.
  \end{gather*}
  Substituting these coefficient bounds into~\eqref{eq:optimal_energy_combined} proves~\eqref{eq:optimal_one_step}.

\label{lem:optimal_error_moments}
  For every $t\geq1$ and integer $T\geq1$,
  \begin{equation}
    \label{eq:optimal_error_budget}
    \begin{aligned}
      \mathbb{E}\left[\delta_t\mid\mathcal F_{t-1}\right]
      &\leq\sigma_2D\sqrt t+2\sigma_1t^2,\\
      \sum_{i=1}^T\mathbb{E}\left[\delta_i\mid\mathcal F_{i-1}\right]
      &\leq2\lambda_TD^2.
    \end{aligned}
  \end{equation}
  Moreover,
  \begin{equation}
    \label{eq:optimal_error_second_moment}
    \mathbb{E}\left[\delta_t^2\mid\mathcal F_{t-1}\right]
    \leq\frac{3D^2\sigma_2^2}{\alpha_t^2}
    +\frac{6\sigma_1^2t^3}{\alpha_t^2}.
  \end{equation}

\begin{itemize}
\item We bound first moment. Taking the quadratic bound in each minimum gives
\begin{equation*}
  \delta_t
  \leq\frac{4}{\alpha_t^2\lambda_t}
  \left(\|{H_t-\nabla^2 f(v_t)} \|^2+\frac{t^3}{D^2}\|{g_t-\nabla f(v_t)} \|^2\right)
  +\frac{2t^3}{\alpha_t^2\lambda_tD^2}\|{\widetilde g_t-\nabla f(y_t)} \|^2.
\end{equation*}
Taking conditional expectations and using~\eqref{eq:stoch_grad} and~\eqref{eq:stoch_hess}, with conditioning first on $\mathcal G_t$ for $\widetilde g_t$, we obtain
\begin{equation*}
  \mathbb{E}\left[\delta_t\mid\mathcal F_{t-1}\right]
  \leq\frac{4\sigma_2^2}{\alpha_t^2\lambda_t}
  +\frac{6\sigma_1^2t^3}{\alpha_t^2\lambda_tD^2}.
\end{equation*}
For $t\geq3$, $\alpha_t^{-1}=(t+3)/4\leq t/2$, so
\begin{equation*}
  \mathbb{E}\left[\delta_t\mid\mathcal F_{t-1}\right]
  \leq\frac{\sigma_2^2t^2}{\lambda_t}
  +\frac{3\sigma_1^2t^5}{2\lambda_tD^2}
  \stackrel{\eqref{eq:optimal_reg}}{\leq}
  \sigma_2D\sqrt t+\frac{3}{2}\sigma_1t^2.
\end{equation*}
For $t=1,2$, we use the linear bounds to obtain better constants. Using $\alpha_t^{-1}\leq\sqrt t$ gives
\begin{equation*}
  \mathbb{E}\left[\delta_t\mid\mathcal F_{t-1}\right]
  \leq\frac{\sigma_2D+2\sigma_1t^{3/2}}{\alpha_t}
  \leq\sigma_2D\sqrt t+2\sigma_1t^2.
\end{equation*}
Thus the first bound in~\eqref{eq:optimal_error_budget} holds for every $t\geq1$. By Cauchy--Schwarz and the formula for the sum of squares,
\begin{gather*}
  \sum_{t=1}^T\mathbb{E}\left[\delta_t\mid\mathcal F_{t-1}\right]
  \leq\sigma_2D\sum_{t=1}^T\sqrt t+2\sigma_1\sum_{t=1}^Tt^2
  \leq\sigma_2DT\sqrt{\frac{T+1}{2}}
  +\frac{\sigma_1T(T+1)(2T+1)}{3}\\
  \leq\sigma_2DT^{3/2}+2\sigma_1T^3
  \stackrel{\eqref{eq:optimal_reg}}{\leq}2\lambda_TD^2.
\end{gather*}

\item Now, we bound second moment. Taking the linear bounds and squaring gives
\begin{gather*}
  \delta_t^2
  \leq\left(
    \frac{D}{\alpha_t}\|{H_t-\nabla^2 f(v_t)} \|
    +\frac{t^{3/2}}{\alpha_t}\|{g_t-\nabla f(v_t)} \|
    +\frac{t^{3/2}}{\alpha_t}\|{\widetilde g_t-\nabla f(y_t)} \|
  \right)^2\\
  \leq\frac{3D^2}{\alpha_t^2}\|{H_t-\nabla^2 f(v_t)} \|^2
  +\frac{3t^3}{\alpha_t^2}
  \|{g_t-\nabla f(v_t)} \|^2+\frac{3t^3}{\alpha_t^2} \|{\widetilde g_t-\nabla f(y_t)} \|^2.
\end{gather*}
Taking conditional expectations as above, we obtain
\begin{equation*}
  \mathbb{E}\left[\delta_t^2\mid\mathcal F_{t-1}\right]
  \leq\frac{3D^2\sigma_2^2}{\alpha_t^2}
  +\frac{6\sigma_1^2t^3}{\alpha_t^2}.
\end{equation*}
\end{itemize}

For every integer $T\geq1$,
  \begin{equation}
    \label{eq:optimal_energy_moments}
    \mathbb{E} E_T\leq\frac{5}{2}\lambda_TD^2,
    \qquad
    \left(\mathbb{E} E_T^2\right)^{1/2}\leq5\lambda_TD^2.
  \end{equation}

Summing~\eqref{eq:optimal_one_step} and using $E_0\leq\lambda_0D^2/2$, we obtain
  \begin{equation}
    \label{eq:optimal_summed_energy}
      0\leq E_T+\frac{1}{8}\sum_{t=1}^T\frac{a_t\tau_t}{\alpha_t}\|{s_t} \|^2
      \leq E_0+\frac{D^2}{2}(\lambda_T-\lambda_0)
      +\sum_{t=1}^T\delta_t+\sum_{t=1}^T\ell_t
      \leq\frac{\lambda_TD^2}{2}
      +\sum_{t=1}^T\delta_t+\sum_{t=1}^T\ell_t,
  \end{equation}
  where $\ell_t=-a_t\left\langle\widetilde g_t-\nabla f(y_t),z_{t-1}-x^*\right\rangle$.

  The points $y_t,z_{t-1}$ and the weight $a_t$ are determined before sampling $\widetilde\xi_t$. Thus,
  \begin{equation}
    \label{eq:optimal_ell_second_moment}
      \mathbb{E}\left[\ell_t^2\mid\mathcal G_t\right]
      \leq a_t^2D^2\mathbb{E}\left[\|{\widetilde g_t-\nabla f(y_t)} \|^2\mid\mathcal G_t\right]
      \stackrel{\eqref{eq:stoch_grad}}{\leq}a_t^2D^2\sigma_1^2
      \stackrel{\eqref{eq:optimal_weight_bound}}{\leq}
      \frac{\sigma_1^2t^3}{\alpha_t^2}
      \leq\sigma_1^2t^5.
  \end{equation}
  Moreover,
  \begin{equation*}
    \mathbb{E}\left[\ell_t\mid\mathcal G_t\right]
    =-a_t\left\langle\mathbb{E}\left[\widetilde g_t\mid\mathcal G_t\right]-\nabla f(y_t),z_{t-1}-x^*\right\rangle
    \stackrel{\eqref{eq:unbiased_grad}}{=}0.
  \end{equation*}
  Taking expectations in~\eqref{eq:optimal_summed_energy} gives
  \begin{gather*}
    \mathbb{E} E_T
    \leq\frac{\lambda_TD^2}{2}
    +\sum_{t=1}^T\mathbb{E}\delta_t+\sum_{t=1}^T\mathbb{E}\ell_t
    =\frac{\lambda_TD^2}{2}+\sum_{t=1}^T\mathbb{E}\delta_t
    \stackrel{\eqref{eq:optimal_error_budget}}{\leq}
    \frac{\lambda_TD^2}{2}+2\lambda_TD^2
    =\frac{5}{2}\lambda_TD^2.
  \end{gather*}

  Using~\eqref{eq:optimal_summed_energy} and applying Minkowski's inequality twice, we obtain
  \begin{equation}
    \label{eq:optimal_energy_second_split}
    \left(\mathbb{E} E_T^2\right)^{1/2}
    \leq\frac{\lambda_TD^2}{2}
    +\left(\mathbb{E}\left(\sum_{t=1}^T\delta_t\right)^2\right)^{1/2}
    +\left(\mathbb{E}\left(\sum_{t=1}^T\ell_t\right)^2\right)^{1/2},
  \end{equation}
  since sums have finite second moments by~\eqref{eq:optimal_error_second_moment} and~\eqref{eq:optimal_ell_second_moment}.
  It remains to bound the second moments of the two sums in~\eqref{eq:optimal_energy_second_split}.

  For the first sum,
  \begin{equation}
    \label{eq:optimal_error_sum_expansion}
    \mathbb{E}\left(\sum_{t=1}^T\delta_t\right)^2
    =\sum_{t=1}^T\mathbb{E}\delta_t^2
    +2\sum_{1\leq i<j\leq T}\mathbb{E}\left[\delta_i\delta_j\right].
  \end{equation}
  For $i<j$, $\delta_i$ is determined before iteration $j$. Therefore, by the law of total expectation
  \begin{gather*}
    \mathbb{E}\left[\delta_i\delta_j\right]
    =\mathbb{E}\left[\delta_i\mathbb{E}\left[\delta_j\mid\mathcal F_{j-1}\right]\right]
    \stackrel{\eqref{eq:optimal_error_budget}}{\leq}
    (\sigma_2D\sqrt j+2\sigma_1j^2)\mathbb{E}\delta_i
    \stackrel{\eqref{eq:optimal_error_budget}}{\leq}
    (\sigma_2D\sqrt i+2\sigma_1i^2)
    (\sigma_2D\sqrt j+2\sigma_1j^2).
  \end{gather*}
  By the law of total expectation and~\eqref{eq:optimal_error_second_moment},
  \begin{equation*}
    \mathbb{E}\delta_t^2
    =\mathbb{E}\left[\mathbb{E}\left[\delta_t^2\mid\mathcal F_{t-1}\right]\right]
    \leq\frac{3D^2\sigma_2^2+6\sigma_1^2t^3}{\alpha_t^2}
    \leq3D^2\sigma_2^2t^2+6\sigma_1^2t^5.
  \end{equation*}
  Substituting these bounds into~\eqref{eq:optimal_error_sum_expansion}, we obtain
  \begin{equation}
    \label{eq:optimal_error_sum_moment}
    \begin{aligned}
      \mathbb{E}\left(\sum_{t=1}^T\delta_t\right)^2
      &\leq3D^2\sigma_2^2\sum_{t=1}^Tt^2
      +6\sigma_1^2\sum_{t=1}^Tt^5
      +\left(\sum_{t=1}^T(\sigma_2D\sqrt t+2\sigma_1t^2)\right)^2\\
      &\leq3D^2\sigma_2^2T^3+6\sigma_1^2T^6
      +(\sigma_2DT^{3/2}+2\sigma_1T^3)^2
      \leq10(\sigma_2DT^{3/2}+\sigma_1T^3)^2
      \stackrel{\eqref{eq:optimal_reg}}{\leq}10\lambda_T^2D^4.
    \end{aligned}
  \end{equation}

  For the sum of $\ell_t$, the zero conditional means imply that the cross terms vanish. For $i<j$,
  \begin{equation*}
    \mathbb{E}\left[\ell_i\ell_j\right]
    =\mathbb{E}\left[\ell_i\mathbb{E}\left[\ell_j\mid\mathcal G_j\right]\right]=0.
  \end{equation*}
  Consequently,
  \begin{equation}
    \label{eq:optimal_stochastic_sum_moments}
      \mathbb{E}\left(\sum_{t=1}^T\ell_t\right)^2
      =\sum_{t=1}^T\mathbb{E}\ell_t^2
      \stackrel{\eqref{eq:optimal_ell_second_moment}}{\leq}
      \sigma_1^2\sum_{t=1}^Tt^5
      =\frac{\sigma_1^2T^2(T+1)^2(2T^2+2T-1)}{12}
      \leq\sigma_1^2T^6
      \stackrel{\eqref{eq:optimal_reg}}{\leq}\lambda_T^2D^4.
  \end{equation}

  Substituting~\eqref{eq:optimal_error_sum_moment} and~\eqref{eq:optimal_stochastic_sum_moments} into~\eqref{eq:optimal_energy_second_split}, we obtain
  \begin{equation*}
    \left(\mathbb{E} E_T^2\right)^{1/2}
    \leq\left(\frac{1}{2}+\sqrt{10}+1\right)\lambda_TD^2
    \leq5\lambda_TD^2.
  \end{equation*}
  This proves~\eqref{eq:optimal_energy_moments}.

For every integer $T\geq1$,
  \begin{equation}
    \label{eq:optimal_inverse_step_sum}
    A_T^{-1}\leq\frac{128D}{T^{7/2}}
    +\frac{256}{T^4}
    \sum_{\substack{2\leq t\leq T\\a_t<\alpha_tA_t}}\frac{\|{s_t} \|}{\alpha_t}.
  \end{equation}

For $t\geq2$ with $a_t<\alpha_tA_t$, we have $0<\alpha_t<1$ and
  \begin{equation*}
    A_t=A_{t-1}+a_t
    =(1-\alpha_t)\frac{A_{t-1}}{1-\alpha_t}
    +\alpha_t\frac{a_t}{\alpha_t}.
  \end{equation*}
  By convexity of $1/x$
  \begin{equation}
    \label{eq:optimal_inverse_step}
    \begin{aligned}
      \frac1{A_t}
      \leq(1-\alpha_t)\frac1{A_{t-1}/(1-\alpha_t)}
      +\alpha_t\frac1{a_t/\alpha_t}
      =\frac{(1-\alpha_t)^2}{A_{t-1}}+\frac{\alpha_t^2}{a_t}
      \stackrel{\eqref{eq:optimal_damped_weight}}{\leq}
      \frac{1-\alpha_t}{A_{t-1}}
      +\frac{D\alpha_t^3}{t^{3/2}}+\alpha_t^3\|{s_t} \|.
    \end{aligned}
  \end{equation}
For $t\geq2$ with $a_t<\alpha_tA_t$, multiplying inequality above by $t(t+1)(t+2)(t+3)$ and substituting $\alpha_t=4/(t+3)$ gives
\begin{gather*}
  \frac{t(t+1)(t+2)(t+3)}{A_t}
  -\frac{(t-1)t(t+1)(t+2)}{A_{t-1}}\\
  \leq\frac{64D}{\sqrt t}\frac{(t+1)(t+2)}{(t+3)^2}
  +256\frac{t(t+1)(t+2)}{(t+3)^3}\frac{\|{s_t} \|}{\alpha_t}\\
  \leq\frac{64D}{\sqrt t}+256\frac{\|{s_t} \|}{\alpha_t}.
\end{gather*}

For $a_t=\alpha_tA_t$, we have equality:
  \begin{equation*}
      \frac1{A_t}
      =(1-\alpha_t)\frac1{A_{t-1}/(1-\alpha_t)}
      +\alpha_t\frac1{a_t/\alpha_t}
      =
      \frac{1-\alpha_t}{A_{t-1}}.
  \end{equation*}

For $t\geq2$ with $a_t=\alpha_tA_t$, multiplying the equality above by the same factor gives
\begin{equation*}
  \frac{t(t+1)(t+2)(t+3)}{A_t}
  -\frac{(t-1)t(t+1)(t+2)}{A_{t-1}}=0.
\end{equation*}
Summing these two relations over $t=2,\ldots,T$, we obtain
\begin{gather*}
  \frac{T(T+1)(T+2)(T+3)}{A_T}
  \leq\frac{24}{A_1}
  +\sum_{\substack{2\leq t\leq T\\a_t<\alpha_tA_t}}
  \left(\frac{64D}{\sqrt t}+256\frac{\|{s_t} \|}{\alpha_t}\right)
  \leq\frac{24}{A_1}+64D\sum_{t=2}^T\frac1{\sqrt t}
  +256\sum_{\substack{2\leq t\leq T\\a_t<\alpha_tA_t}}\frac{\|{s_t} \|}{\alpha_t}\\
  \leq48D+128D(\sqrt T-1)
  +256\sum_{\substack{2\leq t\leq T\\a_t<\alpha_tA_t}}\frac{\|{s_t} \|}{\alpha_t}
  \leq128D\sqrt T
  +256\sum_{\substack{2\leq t\leq T\\a_t<\alpha_tA_t}}\frac{\|{s_t} \|}{\alpha_t}.
\end{gather*}
Here we used
\begin{equation}
  \label{eq:optimal_inverse_sqrt_sum}
  A_1^{-1}\stackrel{\eqref{eq:optimal_initialization}}{=}\frac{\tau_1}{\lambda_1}
  =D+\|{s_1} \|\stackrel{\eqref{eq:optimal_geometry}}{\leq}2D \quad \text{and} \quad \sum_{t=1}^T\frac1{\sqrt t}\leq2\sqrt T-1.
\end{equation}
Dividing by $T(T+1)(T+2)(T+3)\geq T^4$ proves~\eqref{eq:optimal_inverse_step_sum}.

\label{lem:optimal_movement}
  For every integer $T\geq1$,
  \begin{equation}
    \label{eq:optimal_movement_bounds}
    \mathbb{E}\sum_{t=1}^T\sqrt t V_t\leq76D^2\sqrt T,
    \qquad
    \mathbb{E}\left(\sum_{t=1}^T\sqrt{V_t}\right)^2\leq152D^2T.
  \end{equation}

Dividing~\eqref{eq:optimal_one_step} by $\lambda_t$, taking expectations, and using $\mathbb{E}\ell_t=0$, we get
  \begin{equation}
    \label{eq:Vt_bound}
    \frac18\mathbb{E} V_t
    \leq\frac{\mathbb{E} E_{t-1}}{\lambda_t}-\frac{\mathbb{E} E_t}{\lambda_t}
    +\frac{D^2}{2}\left(1-\frac{\lambda_{t-1}}{\lambda_t}\right)
    +\frac{\mathbb{E}\delta_t}{\lambda_t}.
  \end{equation}
  We bound the third term first. By the definition of $\lambda_t$ in~\eqref{eq:optimal_reg}, for $t\geq2$,
  \begin{gather*}
    \lambda_{t-1}
    =\frac{\sigma_1t^3}{D^2}\left(1-\frac1t\right)^3
    +\frac{\sigma_2t^{3/2}}{D}\left(1-\frac1t\right)^{3/2}+2M\\
    \geq\left(1-\frac1t\right)^3
    \left(\frac{\sigma_1t^3}{D^2}+\frac{\sigma_2t^{3/2}}{D}+2M\right)
    =\left(1-\frac1t\right)^3\lambda_t.
  \end{gather*}
  Since $\lambda_t\geq\lambda_{t-1}$,
  \begin{equation*}
    0\leq1-\frac{\lambda_{t-1}}{\lambda_t}
    \leq\frac3t-\frac3{t^2}+\frac1{t^3}\leq\frac3t.
  \end{equation*}
  The last bound also holds at $t=1$ because $\lambda_0=\lambda_1$. 

  Next, we bound the last term in~\eqref{eq:Vt_bound}
  \begin{equation*}
    \frac{\mathbb{E}\delta_t}{\lambda_t}
    \stackrel{\eqref{eq:optimal_error_budget} }{\leq}\frac{\sigma_2D\sqrt t+2\sigma_1t^2}{\lambda_t}
    \leq\frac{2D^2}{t}
    \frac{\sigma_2t^{3/2}/D+\sigma_1t^3/D^2}{\lambda_t}
    \stackrel{\eqref{eq:optimal_reg}}{\leq}\frac{2D^2}{t}.
  \end{equation*}
  Substituting these bounds into~\eqref{eq:Vt_bound} and using $\lambda_t\geq\lambda_{t-1}$ gives
  \begin{equation}
    \label{eq:optimal_normalized_step}
    \frac18\mathbb{E} V_t
    \leq\frac{\mathbb{E} E_{t-1}}{\lambda_{t-1}}-\frac{\mathbb{E} E_t}{\lambda_t}
    +\frac{7D^2}{2t}.
  \end{equation}
  Multiplying~\eqref{eq:optimal_normalized_step} by $\sqrt t$ and summing gives
  \begin{gather*}
    \frac18\mathbb{E}\sum_{t=1}^T\sqrt t V_t
    \leq\sum_{t=1}^T\sqrt t\left(
      \frac{\mathbb{E} E_{t-1}}{\lambda_{t-1}}-\frac{\mathbb{E} E_t}{\lambda_t}\right)
    +\frac{7D^2}{2}\sum_{t=1}^T\frac1{\sqrt t}\\
    =\frac{E_0}{\lambda_0}
    +\sum_{t=1}^{T-1}(\sqrt{t+1}-\sqrt t)\frac{\mathbb{E} E_t}{\lambda_t}
    -\sqrt T\frac{\mathbb{E} E_T}{\lambda_T}
    +\frac{7D^2}{2}\sum_{t=1}^T\frac1{\sqrt t}\\
    \stackrel{\eqref{eq:optimal_energy_moments},\eqref{eq:optimal_inverse_sqrt_sum}}{\leq}
    \frac{D^2}{2}+\frac{5D^2}{2}(\sqrt T-1)
    +\frac{7D^2}{2}(2\sqrt T-1)
    =\frac{D^2}{2}(19\sqrt T-11)
    \leq\frac{19D^2}{2}\sqrt T.
  \end{gather*}
  This proves the first bound in~\eqref{eq:optimal_movement_bounds}. By Cauchy--Schwarz,
  \begin{gather*}
    \left(\sum_{t=1}^T\sqrt{V_t}\right)^2
    =\left(\sum_{t=1}^Tt^{-1/4}\left( t^{1/4}\sqrt{V_t}\right)\right)^2
    \leq\left(\sum_{t=1}^T\frac1{\sqrt t}\right)
          \left(\sum_{t=1}^T\sqrt t V_t\right),\\
    \mathbb{E}\left(\sum_{t=1}^T\sqrt{V_t}\right)^2
    \stackrel{\eqref{eq:optimal_inverse_sqrt_sum}}{\leq}
    (2\sqrt T-1)\mathbb{E}\sum_{t=1}^T\sqrt t V_t
    \leq(2\sqrt T-1)76D^2\sqrt T
    \leq152D^2T.
  \end{gather*}

Let $f$ be convex and satisfy Assumption~\ref{as:lip_hess}. Let $g_t$ and $H_t$ satisfy Assumptions~\ref{as:stoch_grad} and~\ref{as:stoch_hess}, respectively. Let $\widetilde g_t$ satisfy Assumptions~\ref{as:stoch_grad} and~\ref{as:unbiased_grad}. Then Algorithm~\ref{alg:optimal_method_appendix} with $M\geq L_2$ and parameters~\eqref{eq:optimal_reg} satisfies, for every integer $T\geq1$,
  \begin{equation*}
    \mathbb{E}\left[ f(w_T)-f^*\right]
    \leq640\left(1+4\sqrt{38}\right)
    \left(\frac{\sigma_1D}{\sqrt T}
    +\frac{\sigma_2D^2}{T^2}+\frac{2MD^3}{T^{7/2}}\right).
  \end{equation*}

Substituting~\eqref{eq:optimal_movement_bounds} into~\eqref{eq:optimal_inverse_reduction} gives
  \begin{equation}
    \label{eq:optimal_inverse_bounds}
    \left(\mathbb{E} A_T^{-2}\right)^{1/2}
    \leq\frac{128D}{T^{7/2}}
    +\frac{512\sqrt{38}D\sqrt T}{T^4}
    =128\left(1+4\sqrt{38}\right)\frac{D}{T^{7/2}}.
  \end{equation}

  Combining~\eqref{eq:optimal_energy_moments} and~\eqref{eq:optimal_inverse_bounds} in~\eqref{eq:goal}, we conclude that
  \begin{gather*}
    \mathbb{E}\left[ f(w_T)-f^*\right]
    \leq640\left(1+4\sqrt{38}\right)\frac{\lambda_TD^3}{T^{7/2}}
    \stackrel{\eqref{eq:optimal_reg}}{=}
    640\left(1+4\sqrt{38}\right)
    \left(\frac{\sigma_1D}{\sqrt T}
    +\frac{\sigma_2D^2}{T^2}+\frac{2MD^3}{T^{7/2}}\right).
  \end{gather*}
